from sympy import symbols, Product, factorial, simplify

N = symbols('N')

# T1_n = N^n * N! / (N+n)!
def T1_n(n, N):
    return (N**n) * factorial(N) / factorial(N + n)

# T2_n = (N-1)! / (N^n * (N-n-1)!)
def T2_n(n, N):
    return factorial(N - 1) / (N**n * factorial(N - n - 1))

print("--- T1_n for small n ---")
for n in [1, 2]:
    print(f"T1_{n}: {simplify(T1_n(n, N))}")

print("\n--- T2_n for small n ---")
for n in [1, 2]:
    print(f"T2_{n}: {simplify(T2_n(n, N))}")

# Check T1_1 - T2_1
T1_1 = T1_n(1, N)
T2_1 = T2_n(1, N)
print(f"\nT1_1 - T2_1: {simplify(T1_1 - T2_1)}")
